WITH prev_events AS (SELECT *, LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) AS prev_paid_at FROM payments), flagged AS (SELECT *, CASE WHEN prev_paid_at IS NULL OR paid_at > prev_paid_at + INTERVAL '14' DAY THEN 1 ELSE 0 END AS is_new_session FROM prev_events), islands AS (SELECT id, amount, paid_at, status, SUM(is_new_session) OVER (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT id, amount, status, session_no, CASE WHEN status RLIKE '^(SUCCESS|REFUNDED)$' THEN 'GROUP_A' WHEN status RLIKE '^(FAILED)$' THEN 'CORE' ELSE 'GROUP_B' END AS status_zone FROM islands ORDER BY id DESC NULLS FIRST LIMIT 10
